class Solution {
public:
    string frequencySort(string s) {
        int freq[128] = {0};
        for (char c : s) {
            freq[c]++;
        }

        vector<pair<int, char>> chars;
        for (int i = 0; i < 128; i++) {
            if (freq[i] > 0) {
                chars.push_back({freq[i], (char)i});
            }
        }

        sort(chars.begin(), chars.end(), [](const pair<int,char>& a, const pair<int,char>& b) {
            return a.first > b.first;
        });

        string result;
        result.reserve(s.size());
        for (auto& p : chars) {
            result.append(p.first, p.second);
        }

        return result;
    }
};
